import {reading,colour,probeReading} from './titration-model.js';
const line='stroke="#354f60" stroke-width="2.5" stroke-linejoin="round"';
export function art(o,s){let drawing='',w=80,h=110;
 if(o.kind==='burette'){w=40;h=250;const y=225*(1-o.water/50);drawing=`<path d="M-12 0V225H12V0" fill="url(#glass)" ${line}/><rect x="-8" y="${y}" width="16" height="${225-y}" fill="#a4d3dc" opacity=".65"/>${Array.from({length:51},(_,i)=>`<path d="M-10 ${i*4.5}h${i%5===0?14:7}" stroke="#607c85" stroke-width="1"/>${i%10===0?`<text x="19" y="${i*4.5+4}" font-size="11">${i}</text>`:''}`).join('')}<path d="M0 225V250" ${line}/><path d="M-17 231H17" stroke="#547a7d" stroke-width="7"/><circle cy="231" r="6" fill="#a1b6ae"/>${o.tip.water<.199?'<ellipse cy="240" rx="3" ry="7" fill="#fff8da"/>':''}`;}
 else if(o.kind==='clampStand'){w=150;h=17;drawing=`<rect x="-5" y="-320" width="10" height="320" fill="url(#metal)" ${line}/><rect x="-70" y="1" width="140" height="16" fill="#809797" ${line}/><path d="M0-275H130" ${line}/><path d="M117-285V-265M143-285V-265" ${line}/>`;}
 else if(o.kind==='transferFunnel'){w=60;h=60;drawing=`<path d="M-30 0H30L3 30V60H-3V30Z" fill="url(#glass)" ${line}/>`;}
 else if(o.kind==='pipette'||o.kind==='probe'){w=30;h=110;drawing=o.kind==='pipette'?`<path d="M-3 8V110H3V8" fill="url(#glass)" ${line}/><ellipse cy="45" rx="10" ry="24" fill="${o.water>0?'#a1cdd5':'url(#glass)'}" ${line}/><ellipse cy="0" rx="14" ry="17" fill="#829e98" ${line}/><text x="17" y="45" font-size="11">${o.water.toFixed(2)} mL</text>`:`<rect x="-4" width="8" height="110" rx="3" fill="#7e9c99" ${line}/><rect x="-31" y="-30" width="62" height="36" rx="6" fill="#d9e6d4" ${line}/><text id="ph-reading" x="0" y="-8" text-anchor="middle" font-family="monospace" font-size="13">${probeReading(s)?.toFixed(2)??'—'} pH</text>`;}
 else if(o.kind==='dropper'){w=26;h=50;drawing=`<rect x="-10" width="20" height="34" rx="4" fill="#9aa876" ${line}/><path d="M-4 34V50H4V34" fill="url(#glass)" ${line}/><text y="23" text-anchor="middle" font-size="8">BTB</text>`;}
 else{const flask=o.kind==='conical',bottle=o.kind==='bottle'||o.kind==='wash';w=flask?110:bottle?69:78;h=flask?120:bottle?110:96;
 const outline=flask?'M-32 0V35L-55 115Q-55 120-48 120H48Q55 120 55 115L32 35V0Z':`M${-w/2} 0V${h-5}Q${-w/2} ${h} ${-w/2+5} ${h}H${w/2-5}Q${w/2} ${h} ${w/2} ${h-5}V0Z`;
 const top=h-5-(h-18)*Math.min(1,o.water/(o.id==='waste'?250:o.capacity));drawing=`<defs><clipPath id="inside-${o.id}"><path d="${outline}"/></clipPath></defs><path d="${outline}" fill="url(#glass)" ${line}/><g clip-path="url(#inside-${o.id})">${o.water>0?`<rect x="-${w/2}" y="${top}" width="${w}" height="${h-top}" fill="${colour(o)}" opacity=".8"/><path d="M${-w/2} ${top}H${w/2}" stroke="#88aeb7"/>`:''}</g>`;
 if(bottle)drawing+=`<text y="62" text-anchor="middle" font-size="11">${o.id==='acid'?'HCl · ? M':o.id==='base'?'NaOH':'WATER'}</text>${o.id==='base'?'<text y="78" text-anchor="middle" font-size="10">0.100 M</text>':''}`;
 }
 return `${drawing}<rect class="select-outline" x="${-w/2-8}" y="${o.kind==='clampStand'?-330:-35}" width="${w+16}" height="${o.kind==='clampStand'?360:h+50}" rx="5"/>`;
}
export function buretteView(s){const r=reading(s),floor=Math.floor(r),frac=r-floor,y=45+frac*55;return `<svg viewBox="0 0 180 160" role="img" aria-label="Burette meniscus, scale increases downward"><rect x="55" y="5" width="60" height="150" fill="url(#glass)" stroke="#789395"/><rect x="58" y="${y}" width="54" height="160" fill="#b4d7db"/><path d="M58 ${y-4}Q85 ${y+4}112 ${y-4}" fill="none" stroke="#4f7b85" stroke-width="2"/>${Array.from({length:21},(_,i)=>`<path d="M55 ${45+(i-10)*5.5}h${i%10===0?24:12}" stroke="#597680"/>${i%10===0?`<text x="120" y="${49+(i-10)*5.5}" font-size="12">${floor+(i-10)/10}</text>`:''}`).join('')}</svg><p id="burette-reading">Burette: <strong>${r.toFixed(2)} mL</strong></p><p>Read the bottom of the meniscus; the scale increases downwards.</p>`;}
